import java.util.Set;

/**
 * Rejects an owner whose email address uses a disposable-domain provider. The domain is compared
 * case-insensitively against a small blocklist; an owner with no email is left untouched.
 */
@ControllerAdvice
public class OwnerDisposableEmailAdvice implements Validator {

    private static final Set<String> BLOCKED_DOMAINS = Set.of(
        "mailinator.com", "tempmail.com", "guerrillamail.com");

    @InitBinder
    void registerOwnerDisposableEmailValidator(WebDataBinder binder) {
        binder.addValidators(this);
    }

    @Override
    public boolean supports(Class<?> clazz) {
        return OwnerFieldsDto.class.isAssignableFrom(clazz);
    }

    @Override
    public void validate(Object target, Errors errors) {
        String email = ((OwnerFieldsDto) target).getEmail();
        int at = email == null ? -1 : email.lastIndexOf('@');
        if (at >= 0 && BLOCKED_DOMAINS.contains(email.substring(at + 1).toLowerCase())) {
            errors.rejectValue("email", "email.disposable", "must not use a disposable email domain");
        }
    }
}

